export function Sidebar() {
  const [collapsed, setCollapsed] = useState(false);
  const [expandedMenus, setExpandedMenus] = useState<Set<string>>(new Set(['الحسابات', 'المخازن', 'الموارد البشرية', 'الأصول', 'التقارير']));

  const toggleMenu = (label: string) => {
    setExpandedMenus((prev) => {
      const next = new Set(prev);
      if (next.has(label)) next.delete(label);
      else next.add(label);
      return next;
    });
  };

  return (
    <aside
      className={`${
        collapsed ? 'w-16' : 'w-60'
      } bg-slate-800 dark:bg-slate-950 text-white flex flex-col transition-all duration-200 flex-shrink-0`}
    >
      <div className="h-16 flex items-center justify-center border-b border-slate-700">
        {!collapsed && <span className="font-bold text-sm whitespace-nowrap">نظام الموبايلات</span>}
      </div>

      <nav className="flex-1 py-4 space-y-1 overflow-y-auto overflow-x-hidden">
        {menuItems.map((item) => {
          const Icon = item.icon;
          if (!item.children) {
            return (
              <NavLink
                key={item.label}
                to={item.path!}
                end={item.path === '/'}
                className={({ isActive }) =>
                  `flex items-center gap-3 mx-2 px-3 py-2.5 rounded-lg transition-colors ${
                    isActive
                      ? 'bg-primary-600 text-white'
                      : 'text-slate-300 hover:bg-slate-700 hover:text-white'
                  }`
                }
                title={item.label}
              >
                <Icon size={20} className="flex-shrink-0" />
                {!collapsed && <span className="text-sm whitespace-nowrap">{item.label}</span>}
              </NavLink>
            );
          }
          return (
            <div key={item.label}>
              <button
                onClick={() => toggleMenu(item.label)}
                className="w-full flex items-center gap-3 mx-2 px-3 py-2.5 rounded-lg text-slate-300 hover:bg-slate-700 hover:text-white transition-colors"
                title={item.label}
              >
                <Icon size={20} className="flex-shrink-0" />
                {!collapsed && (
                  <>
                    <span className="text-sm whitespace-nowrap flex-1 text-right">{item.label}</span>
                    {expandedMenus.has(item.label) ? (
                      <ChevronDown size={14} />
                    ) : (
                      <ChevronLeft size={14} />
                    )}
                  </>
                )}
              </button>
              {!collapsed && expandedMenus.has(item.label) && (
                <div className="mr-4 space-y-0.5">
                  {item.children.map((child) => {
                    const ChildIcon = child.icon;
                    return (
                      <NavLink
                        key={child.path}
                        to={child.path}
                        className={({ isActive }) =>
                          `flex items-center gap-2 mx-2 px-3 py-2 rounded-lg text-xs transition-colors ${
                            isActive
                              ? 'bg-primary-600/80 text-white'
                              : 'text-slate-400 hover:bg-slate-700/50 hover:text-white'
                          }`
                        }
                      >
                        <ChildIcon size={14} className="flex-shrink-0" />
                        <span className="whitespace-nowrap">{child.label}</span>
                      </NavLink>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </nav>

      <button
        onClick={() => setCollapsed(!collapsed)}
        className="h-10 flex items-center justify-center border-t border-slate-700 text-slate-400 hover:text-white hover:bg-slate-700 transition-colors"
      >
        {collapsed ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
      </button>
    </aside>
  );
}

