            سيتم إنشاء كود تفعيل فريد مرتبط بجهاز العميل عند الاستخدام. لا يمكن إعادة استخدام الكود.
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { ipcMain } from 'electron';
import bcrypt from 'bcryptjs';
import { getDb } from '../database/connection';

export function registerAuthHandlers() {
  ipcMain.handle('auth:login', async (_event, { username, password }: { username: string; password: string }) => {
    const db = getDb();

    const user = db.prepare(`
      SELECT u.UserID, u.Username, u.EmployeeID, u.PasswordHash, u.IsActive,
             e.Name as EmployeeName, r.RoleID, r.RoleName
      FROM users u
      LEFT JOIN employees e ON u.EmployeeID = e.EmployeeID
      LEFT JOIN roles r ON u.RoleID = r.RoleID
      WHERE u.Username = ? AND u.IsActive = 1
    `).get(username) as any;

    if (!user) {
      return { success: false, message: 'المستخدم غير موجود أو غير نشط' };
    }

    const valid = bcrypt.compareSync(password, user.PasswordHash);
    if (!valid) {
      return { success: false, message: 'كلمة المرور غير صحيحة' };
    }

    return {
      success: true,
      user: {
        userId: user.UserID,
        username: user.Username,
        employeeId: user.EmployeeID,
        employeeName: user.EmployeeName,
        roleId: user.RoleID,
        roleName: user.RoleName,
      },
    };
  });
}

import { create } from 'zustand';

interface AuthUser {
  userId: number;
  username: string;
  employeeId?: number;
  employeeName?: string;
  roleId: number;
  roleName: string;
}

interface AuthState {
  isAuthenticated: boolean;
  user: AuthUser | null;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
  initAuth: () => Promise<void>;
}

export const useAuthStore = create<AuthState>((set) => ({
  isAuthenticated: false,
  user: null,

  login: async (username: string, password: string) => {
    try {
      const result = await window.api.invoke('auth:login', { username, password });
      if (result.success) {
        set({ isAuthenticated: true, user: result.user });
        return true;
      }
      return false;
    } catch {
      return false;
    }
  },

  logout: () => {
    set({ isAuthenticated: false, user: null });
  },

  initAuth: async () => {
    // Check if there's a saved session (could be enhanced with electron-store)
    // For now, just set not authenticated
    set({ isAuthenticated: false });
  },
}));

